function sortColors(nums) {
    let l = 0, r = nums.length - 1, i = 0;
    while (i <= r) {
        if (nums[i] === 0) {
            [nums[l], nums[i]] = [nums[i], nums[l]];
            l++;
            i++;
        } else if (nums[i] === 2) {
            [nums[i], nums[r]] = [nums[r], nums[i]];
            r--;
        } else {
            i++;
        }
    }
    return nums;
}
